security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['editWorkOrders']['enabled']: 
		canCreate = True
		canEdit = True if value['workOrderId']is not None else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

messageHandlers.script:
system.perspective.print("userResponseDelete() msg rcvd with %s"%payload)

if payload['userInput'] == 'OK': self.deleteWorkOrderEvent()

return

system.perspective.print("openWorkOrderEvent() msg rcvd with %s"%payload)

if payload['workOrderId'] is None:
	self.view.custom.workOrders = {'selectedWorkOrderEventId': None, 'selectedWorkOrderId': None}
	self.view.custom.addMode = True
	system.perspective.print("Setting workOrders to %s"%self.view.custom.workOrders)
else:
	workOrderEventInfo = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.cmms.getWorkOrders({'workOrderId': payload['workOrderId']}),0)
	workOrderEventInfo['dueDate'] = system.date.now()
	self.view.custom.addMode = False
	workOrderEventId, msg = system.kanoa.cmms.addWorkOrderScheduleEvent(workOrderEventInfo, self.view.custom.security.userId)
	self.view.custom.workOrders = {'selectedWorkOrderEventId': workOrderEventId, 'selectedWorkOrderId': None}		

	system.perspective.sendMessage('refreshWorkOrders', {})

return
